const input = $input.first().json || {};
const headers = input.headers || {};
const body = input.body || input;
const secret = String($env.N8N_WEBHOOK_SECRET || '').trim();
const incoming = String(headers['x-webhook-secret'] || headers['X-Webhook-Secret'] || '').trim();
if (secret && incoming !== secret) throw new Error('Invalid webhook secret');

const flowEnv = String($env.FLOW_ENV || 'staging').toLowerCase();
if (flowEnv !== 'staging') throw new Error('FLOW_ENV must be staging');

const phone = String(body.phone || body.paciente_telefone || '').replace(/\D/g, '');
if (!phone) throw new Error('phone required');

const message = String(body.message || 'Após avaliação médica, não foi possível aprovar sua renovação de receita por teleconsulta. Recomendamos atendimento presencial para melhor avaliação.');
const dryRun = body.dryRun === true || String($env.WHATSAPP_DRY_RUN || 'true') === 'true';

const evoUrl = String($env.EVOLUTION_API_URL || '').replace(/\/$/, '').replace(/\.railway\.internal.*/, '.up.railway.app');
const evoKey = String($env.EVOLUTION_API_KEY || $env.AUTHENTICATION_API_KEY || '').trim();
const instance = String($env.EVOLUTION_INSTANCE || 'mdoctor-staging').trim();

return [{ json: { phone, message, dryRun, evoUrl, evoKey, instance, atendimentoId: body.atendimentoId, correlationId: body.correlationId || `reject-${Date.now()}` } }];
